  'dl.docTitle': 'Draft League – drafte dein Traumteam und schlag deine Freunde | CM Reborn', 'dl.cta': 'Draft League erstellen', 'dl.ctaShort': 'Liga erstellen', 'dl.seeHow': 'So funktioniert es', 'dl.back': 'Zurück zu CM Reborn',
  'dl.nav.how': 'So funktioniert es', 'dl.nav.fun': 'Der Spaß', 'dl.nav.shots': 'Screenshots', 'dl.pill': 'Neuer Spielmodus · kostenlos',
  'dl.h1a': 'Drafte dein Traumteam.', 'dl.h1b': 'Schlag deine Freunde.', 'dl.lead': 'Jeder baut einen fiktiven Verein aus den 500 besten Spielern im Spiel – live, Pick für Pick, mit 60 Sekunden auf der Uhr. Dann spielt ihr eine ganze Saison gegeneinander. Wenn sie endet, beginnt ein neuer Draft.',
  'dl.check.free': 'Kostenlos, im Browser', 'dl.check.friends': '2–16 Vereine, mit oder ohne KI', 'dl.check.live': 'Live-Draft mit Sprachchat', 'dl.check.nomoney': 'Keine Gehälter oder Transfers – nur Fußball',
  'dl.floatVoice': '„NEEEIN, der war meiner!“', 'dl.floatSteal': 'Einen Pick vor dir weggeschnappt',
