  'career.unknownFee': "Ablöse unbekannt (oder Leihe)",
  'trophy.board.league': "Der Vorstand würdigt {manager}: {club} ist Meister!", 'trophy.board.league.body': "Der Präsident: „Das ist ein historischer Tag für {club}. {manager} hat uns gegeben, wovon wir geträumt haben – einen Titel. Der Vorstand steht zu 100 % hinter dir, und wir freuen uns schon auf die nächste Saison.“", 'trophy.board.leagueAgain': "Der Vorstand: {manager} schafft es erneut – Titel Nr. {n}!", 'trophy.board.leagueAgain.body': "Der Präsident: „Einmal zu gewinnen ist groß. Es immer wieder zu tun, ist eine Ära. Danke, {manager} – du hast {club} zu einer Dynastie gemacht.“", 'trophy.board.cup': "Der Vorstand gratuliert dir zum {comp}!", 'trophy.board.cup.body': "Der Präsident: „Ein Pokal in der Vitrine – genau für solche Abende machen wir das. Glückwunsch an {manager} und den ganzen Kader.“", 'trophy.board.cupAgain': "Der Vorstand: wieder der {comp} – Titel Nr. {n} unter {manager}!", 'trophy.board.cupAgain.body': "Der Präsident: „Das wird zur Gewohnheit, und zwar zu einer guten. Glückwunsch, {manager}.“", 'trophy.board.europe': "Europäischer Triumph! Der Vorstand ist begeistert vom {comp}", 'trophy.board.europe.body': "Der Präsident: „{club} hat den {comp} gewonnen. Es ist der größte Abend in der modernen Vereinsgeschichte. {manager}, dein Name steht für immer in den Geschichtsbüchern des Vereins.“", 'trophy.board.europeAgain': "Der Vorstand: wieder der {comp} – {manager} ist eine Legende!", 'trophy.board.europeAgain.body': "Der Präsident: „Titel Nr. {n} im {comp}. Es fehlen die Worte. Danke.“", 'trophy.fans.league': "Die Stadt steht kopf – Tausende Fans feiern den Titel", 'trophy.fans.league.body': "Die Straßen sind voller {club}-Trikots, Fahnen und Feuerwerk. Im Fanforum gibt es nur einen Gesang: „{manager}, {manager}, {manager}!“", 'trophy.fans.cup': "Die Fans feiern den {comp}-Sieg die ganze Nacht", 'trophy.fans.cup.body': "Die Ränge sangen noch lange nach dem Schlusspfiff, und der Bus mit dem Pokal wurde vor dem Stadion von jubelnden Fans empfangen.", 'trophy.fans.europe': "Das ganze Land feiert den europäischen Triumph von {club}", 'trophy.fans.europe.body': "Zehntausende Fans empfingen die Mannschaft am Flughafen. „Das werden wir nie vergessen“, heißt es überall.", 'trophy.captain.league': "{player}: „Der ist für dich und die Fans, Trainer“", 'trophy.captain.league.body': "Der Kapitän: „Du hast uns vom ersten Tag an glauben lassen. Jeder in der Kabine würde für dich durch eine Wand gehen. Danke, Trainer.“", 'trophy.captain.cup': "{player}: „Du hast uns im Finale den Glauben gegeben“", 'trophy.captain.cup.body': "Der Kapitän: „Die Ansprache vor dem Spiel hat genau gepasst. Wir wollten das für dich gewinnen.“", 'trophy.captain.europe': "{player}: „Der schönste Abend meines Lebens – danke, Trainer“", 'trophy.captain.europe.body': "Der Kapitän: „Als Junge habe ich davon geträumt, diesen Pokal hochzustemmen. Du hast es möglich gemacht.“", 'trophy.press.league': "Die Zeitung: {manager} – der Architekt des Titels von {club}", 'trophy.press.league.body': "Die Experten sind sich einig: die Taktik, die Transfers und die Fähigkeit, das Beste aus dem Kader herauszuholen, haben den Unterschied gemacht. {manager} gilt bereits als Trainer des Jahres.", 'trophy.press.cup': "Die Zeitung: {manager} holt einen Titel für {club}", 'trophy.press.cup.body': "Pokalwettbewerbe sind launisch, aber {club} hatte auf alles eine Antwort. Ein verdienter Titel für {manager}.", 'trophy.press.europe': "Europa verneigt sich vor {manager}", 'trophy.press.europe.body': "Medien in ganz Europa schreiben über den Triumph von {club} im {comp}. Der Name {manager} ist plötzlich in aller Munde – auch bei den größten Vereinen.", 'fan.ev.trophy': "Titel!",
  'reject.reason.future': "\"Du bist die Zukunft – wir bauen die Mannschaft für Jahre um dich herum\"", 'reject.r.future.2': "{player}: Wow, danke, Trainer. Das bedeutet mir alles. Ich bleibe und beweise, dass du recht hast.", 'reject.r.future.1': "{player}: Schön zu hören. Aber dann will ich auch meine Chance auf dem Platz.", 'reject.r.future.0': "{player}: Die Zukunft? Das glaube ich nicht so ganz – ich sehe ja, wer spielt.", 'reject.r.future.1Calm': "{player}: Danke, Trainer. Ich hatte es mit {club} ohnehin nicht eilig.", 'reject.r.future.0Calm': "{player}: Okay… so interessiert war ich an {club} ohnehin nicht.",
  'talk.future': "Du bist die Zukunft", 'talk.futureHint': "Sag einem Talent, dass es die Zukunft des Vereins ist – wirkt am besten bei jungen Spielern mit großem Potenzial", 'talk.r.futureBelieves': "{player} strahlt: „Danke, Trainer – ich werde härter arbeiten als je zuvor, um dir recht zu geben.“", 'talk.r.futureHopeful': "{player} freut sich: „Das bedeutet mir viel. Ich gebe alles, um meine Chance zu nutzen, wenn sie kommt.“", 'talk.r.futureDoubt': "{player} lächelt höflich, wirkt aber nicht ganz überzeugt.", 'talk.r.futureAgain': "{player}: „Das hast du schon mal gesagt, Trainer. Ich würde es lieber auf dem Platz sehen.“", 'talk.r.futureTooOld': "{player} schaut etwas verwundert – er fühlt sich nicht mehr wie ein junges Talent.",
