  'land.docTitle': 'CM Reborn – der legendäre Fußballmanager, kostenlos im Browser',
  'land.nav.features': 'Features', 'land.nav.screens': 'Screenshots', 'land.nav.ranking': 'Ranglisten', 'land.nav.faq': 'FAQ',
  'land.play': 'Jetzt kostenlos spielen', 'land.playShort': 'Jetzt spielen', 'land.seeScreens': 'Spiel ansehen',
  'land.pill': 'Neue Saison · 40.000+ echte Spieler', 'land.h1a': 'Die Legende ist zurück.', 'land.h1b': 'Jetzt im Browser.',
  'land.lead': 'Der klassische Fußballmanager, wiedergeboren: Bau dein Traumteam, entdecke verborgene Juwelen, stell dich der Presse und führe deinen Verein an die Spitze – mit einer Spiel-Engine, die mitdenkt, und AI-Trainern, die zurückschlagen.',
  'land.check.free': 'Kostenlos', 'land.check.nodl': 'Kein Download', 'land.check.lang': '8 Sprachen', 'land.check.save': 'Speichert automatisch',
  'land.floatGoal': 'TOR! 89. Minute', 'land.floatBid': 'Bieterwettstreit um deinen Star',
  'land.alt.report': 'Spielbericht mit xG, Momentum und Heatmap', 'land.alt.mobile': 'Das Spiel auf dem Handy',
  'land.tick1': '12. Steilpass – und der Ball schlägt im Winkel ein!', 'land.tick2': 'Gerücht: Topklubs beobachten deinen Kapitän', 'land.tick3': '67. Rote Karte! Der Trainer bringt noch einen Stürmer',
  'land.tick4': 'Pressekonferenz: „Glauben Sie noch an den Titel?“', 'land.tick5': 'Scout: „In drei Jahren ist er Weltklasse“', 'land.tick6': 'Berater fordert neuen Vertrag nach fünf Toren in Serie',
  'land.tick7': 'Der Vorstand: „Wir erwarten einen Platz unter den ersten drei“', 'land.tick8': '90.+3 Ausgleich in der Nachspielzeit – das Stadion bebt',
  'land.stat.players': 'echte Spieler in zwei Datenbanken', 'land.stat.clubs': 'Vereine', 'land.stat.leagues': 'Ligen', 'land.stat.moments': 'simulierte Aktionen pro Spiel',
  'land.featuresTitle': 'Alles, was du geliebt hast – und alles, was du immer vermisst hast', 'land.featuresSub': 'Die klassische Tiefe von 2001 mit moderner Engine, schönem Design und Spielspaß auf jedem Bildschirm.',
  'land.f.engine.title': 'Eine Spiel-Engine, die mitdenkt', 'land.f.engine.text': '240 Aktionen pro Spiel, xG, Momentum und Heatmaps. Taktik zählt – und es gibt keine Exploit-Formationen.',
  'land.f.players.title': '40.000+ echte Spieler', 'land.f.players.text': 'Zwei Datenbanken: 22.700 Spieler aus 2026/27 und 18.700 aus der Original-Datenbank von CM 01/02. 38 Ligen und 641 Vereine – von der dänischen Superliga bis zur Premier League und Champions League.',
  'land.f.scouting.title': 'Scouting mit Unsicherheit', 'land.f.scouting.text': 'Deine Scouts sehen Spannen, nicht die Wahrheit. Gute Scouts finden Wunderkinder vor allen anderen.',
  'land.f.press.title': 'Pressekonferenzen und Gespräche', 'land.f.press.text': 'Antworte den Journalisten, lobe die Kabine oder staucht sie zusammen – in deinen eigenen Worten.',
  'land.f.transfers.title': 'Ein lebendiger Transfermarkt', 'land.f.transfers.text': 'Bieterwettstreite, Vereine, die mit höheren Angeboten zurückkommen, Leihen mit Kaufoption und aufdringliche Berater.',
  'land.f.ai.title': 'AI-Gegner mit eigenem Willen', 'land.f.ai.text': 'Trainer, die deine Taktik analysieren und während des Spiels reagieren. Spieler mit Forderungen, Grüppchen und Launen.',
  'land.f.ranking.title': 'Globale Ranglisten', 'land.f.ranking.text': 'Jede Saison bringt Punkte für die geleistete Arbeit. Übertriff die Erwartungen mit einem kleinen Verein und zieh an den Trainern der Großklubs vorbei.',
  'land.f.online.title': 'Online mit Freunden', 'land.f.online.text': 'Führt eure eigenen Vereine in derselben Welt – bietet auf die Spieler der anderen und trefft euch in der Liga.',
  'land.f.mobile.title': 'Überall, auch offline', 'land.f.mobile.text': 'Spiele auf Desktop, Tablet oder Handy. Installiere es als App und mach da weiter, wo du aufgehört hast.',
  'land.nav.looks': 'Looks', 'land.looks.kicker': 'Zwei Looks', 'land.looks.title': 'Modern – oder genau wie 2001', 'land.looks.sub': 'Gleiches Spiel, gleiche Datenbank. Wähle einen modernen, mobilfreundlichen Look oder den klassischen CM 01/02-Stil mit Tabs, Zurück/Weiter und den alten Hintergrundfotos.', 'land.looks.modern': 'Modern', 'land.looks.classic': 'Klassisch CM 01/02', 'land.looks.s.squad': 'Kader', 'land.looks.s.player': 'Spielerprofil', 'land.looks.s.table': 'Tabelle', 'land.looks.modern.text': 'Helles oder dunkles Theme in deinen Vereinsfarben, Seitenmenü, große Zahlen und Diagramme. Gemacht für Handy, Tablet und Desktop.', 'land.looks.classic.text': 'Titelleiste in Vereinsfarben, Tabs, grüne Dropdown-Menüs und der Kader in zwei Spalten – genau wie du es in Erinnerung hast. Mit wechselnden Hintergrundfotos und Pixel-Look.', 'land.looks.play.modern': 'Modern spielen', 'land.looks.play.classic': 'Klassisch spielen', 'land.looks.note': 'Du kannst den Look jederzeit in den Optionen wechseln – sogar mitten in einer Karriere.',
  'land.s.classic.kicker': 'Klassisch CM 01/02', 'land.s.classic.title': 'Genau wie du es in Erinnerung hast', 'land.s.classic.text': 'Schalte das klassische Theme ein, und das Spiel sieht aus und fühlt sich an wie Championship Manager 01/02 – mit Tabs, Zurück/Weiter und den alten Hintergrundfotos.', 'land.s.classic.b1': 'Der Kader in zwei Spalten mit Aufstellung per Drag-and-drop', 'land.s.classic.b2': 'Spielerprofil mit allen Attributen von 1–20 und Spielerkarriere', 'land.s.classic.b3': 'Grüne Dropdown-Menüs, Suchen und Spieler- & Personalsuche',
  'land.alt.classic': 'Das klassische CM 01/02-Theme mit der Datenbank 2001/02',
  'land.rankAiHint': 'Computergesteuerter AI-Trainer', 'land.rankAiNote': 'AI = computergesteuerte Trainer. Spiel eine Saison, und du stehst auf der Liste.',
  'land.nav.join': 'Mitmachen', 'land.join.kicker': 'Mach mit', 'land.join.title': 'Willst du Teil des Projekts sein?', 'land.join.text': 'CM Reborn ist ein Fanprojekt, und helfende Hände sind immer willkommen. Schreib ein paar Zeilen über dich und wobei du helfen möchtest – ich melde mich dann bei dir.', 'land.join.b1': 'Entwickler, Designer und Fußballdaten-Nerds', 'land.join.b2': 'Tester, die neue Features vor allen anderen ausprobieren wollen', 'land.join.b3': 'Übersetzer und Leute, die der Community helfen wollen', 'land.join.name': 'Name', 'land.join.email': 'E-Mail', 'land.join.role': 'Wobei möchtest du helfen?', 'land.join.message': 'Erzähl uns etwas über dich', 'land.join.placeholder': 'Wer bist du, und was möchtest du machen?', 'land.join.role.developer': 'Entwicklung', 'land.join.role.designer': 'Design und Grafik', 'land.join.role.data': 'Daten und Datenbanken', 'land.join.role.testing': 'Testen und Fehlerberichte', 'land.join.role.translation': 'Übersetzung', 'land.join.role.community': 'Community und Inhalte', 'land.join.role.other': 'Sonstiges', 'land.join.send': 'Senden', 'land.join.sending': 'Wird gesendet…', 'land.join.thanks': 'Danke für deine Nachricht!', 'land.join.thanksText': 'Deine Nachricht ist angekommen, ich antworte per E-Mail.', 'land.join.privacy': 'Dein Name und deine E-Mail werden nur verwendet, um dir zu antworten.', 'land.join.offline': 'Das Formular funktioniert nur in der Hauptversion des Spiels.', 'land.join.goLive': 'Zum Formular', 'land.join.err.email': 'Bitte überprüfe deine E-Mail-Adresse.', 'land.join.err.limit': 'Zu viele Nachrichten – bitte versuch es später erneut.', 'land.join.err.missing': 'Bitte gib deinen Namen und eine Nachricht mit mindestens 10 Zeichen ein.', 'land.join.err.other': 'Etwas ist schiefgelaufen – bitte versuch es erneut.',
